// Partial port of compiler/rustc_query_impl/src/self_profile.rs.
// PORT: the self-profiler is a disabled stand-in (rustc_session/stand_ins.ts `SelfProfilerRef`, profiler
// always `None`), so `alloc_self_profile_query_strings` always takes its early return. The string
// builders (`QueryKeyStringCache`, `IntoSelfProfilingString`, ...) are not ported.
import type { TyCtxt } from "../rustc_middle/ty/context.ts";
import { unported } from "../std/panic.ts";

/// All self-profiling events generated by the query engine use
/// virtual `StringId`s for their `event_id`. This method makes all
/// those virtual `StringId`s point to actual strings.
///
/// If we are recording only summary data, the ids will point to
/// just the query names. If we are recording query keys too, we
/// allocate the corresponding strings here.
// rustc: compiler/rustc_query_impl/src/self_profile.rs:184 alloc_self_profile_query_strings
export function alloc_self_profile_query_strings(tcx: TyCtxt): null {
  // `tcx.prof.enabled()` = `self.profiler.is_some()`
  if (!(tcx.prof.profiler !== undefined)) {
    return null;
  }
  return unported("rustc_query_impl::self_profile::alloc_self_profile_query_strings (-Z self-profile)");
}
